function () {
  const start = RoomChecker.toMinutes(InputStart.text);
  const current = RoomChecker.toMinutes(RoomChecker.currentTime);
  const duration = Number(InputDuration.text);
  const blocked = SwitchBlocked.isSwitchedOn;
  let result;
  if (!Number.isFinite(start)) {
    result = {
      available: false,
      reasonCode: "invalid_start",
      message: "Enter a valid start time (HH:MM)."
    };
  } else if (InputDuration.text === "" || InputDuration.text === null || !Number.isInteger(duration) || duration <= 0 || duration > 120) {
    result = {
      available: false,
      reasonCode: "invalid_duration",
      message: "Duration must be a whole number from 1 to 120 minutes."
    };
  } else if (start <= current) {
    result = {
      available: false,
      reasonCode: "past_request",
      message: "Start time must be after 09:00."
    };
  } else if (start + duration > 1440) {
    result = {
      available: false,
      reasonCode: "invalid_interval",
      message: "The booking cannot extend past midnight."
    };
  } else if (blocked) {
    result = {
      available: false,
      reasonCode: "blocked",
      message: "The room is blocked."
    };
  } else {
    const overlap = RoomChecker.bookings.some(booking => {
      const bookingStart = RoomChecker.toMinutes(booking.start);
      const bookingEnd = RoomChecker.toMinutes(booking.end);
      return start < bookingEnd && start + duration > bookingStart;
    });
    result = overlap ? {
      available: false,
      reasonCode: "overlap",
      message: "The requested time overlaps an existing booking."
    } : {
      available: true,
      reasonCode: "available",
      message: "The room is available for this time."
    };
  }
  storeValue("roomResult", result);
  return result;
}

